import { test, expect } from '@playwright/test';

test.describe('Main Layout Horizontal Scroll Disabled on Mobile', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/main-layout');
  });

  test('should disable horizontal scrolling on mobile devices', async ({ page }) => {
    // Set viewport to mobile width
    await page.setViewportSize({ width: 375, height: 812 });

    // Verify horizontal scrollbar is visible
    const scrollbar = page.locator('[data-testid="horizontal-scrollbar"]');
    await expect(scrollbar).toBeVisible();

    // Verify scrollbar is enabled
    const scrollbarState = page.getByRole('status', { name: /scrollable/i });
    await expect(scrollbarState).toBeVisible();

    // Verify horizontal scroll is enabled
    const scrollX = page.getByRole('heading', { name: /scroll/i });
    await expect(scrollX).toBeVisible();

    // Verify content is scrollable horizontally
    const content = page.locator('[data-testid="main-content"]');
    await expect(content).toBeVisible();
    await expect(content).toHaveScrollWidth(expect.gt(0));

    // Scroll to the right edge
    await content.evaluate((el) => {
      el.scrollLeft = el.scrollWidth;
    });

    // Verify scrollbar is still visible
    await expect(scrollbar).toBeVisible();

    // Verify content does not scroll further
    await expect(content).toHaveScrollWidth(expect.equal(content.evaluate((el) => el.scrollWidth)));

    // Verify horizontal scrollbar is disabled
    const scrollbarDisabled = page.getByRole('status', { name: /disabled/i });
    await expect(scrollbarDisabled).toBeVisible();

    // Verify horizontal scroll is disabled
    const scrollXDisabled = page.getByRole('heading', { name: /disabled/i });
    await expect(scrollXDisabled).toBeVisible();

    // Verify content is not scrollable horizontally
    await expect(content).toHaveScrollWidth(expect.equal(content.evaluate((el) => el.scrollWidth)));
  });

  test('should enable horizontal scrolling on desktop devices', async ({ page }) => {
    // Set viewport to desktop width
    await page.setViewportSize({ width: 1280, height: 812 });

    // Verify horizontal scrollbar is not visible
    const scrollbar = page.locator('[data-testid="horizontal-scrollbar"]');
    await expect(scrollbar).not.toBeVisible();

    // Verify scrollbar is disabled
    const scrollbarState = page.getByRole('status', { name: /disabled/i });
    await expect(scrollbarState).toBeVisible();

    // Verify horizontal scroll is disabled
    const scrollX = page.getByRole('heading', { name: /disabled/i });
    await expect(scrollX).toBeVisible();

    // Verify content is not scrollable horizontally
    const content = page.locator('[data-testid="main-content"]');
    await expect(content).toHaveScrollWidth(expect.equal(content.evaluate((el) => el.scrollWidth)));

    // Scroll to the right edge
    await content.evaluate((el) => {
      el.scrollLeft = el.scrollWidth;
    });

    // Verify scrollbar is visible
    await expect(scrollbar).toBeVisible();

    // Verify scrollbar is enabled
    await expect(scrollbarState).toBeVisible();

    // Verify horizontal scroll is enabled
    const scrollXEnabled = page.getByRole('heading', { name: /enabled/i });
    await expect(scrollXEnabled).toBeVisible();

    // Verify content is scrollable horizontally
    await expect(content).toHaveScrollWidth(expect.gt(content.evaluate((el) => el.scrollWidth)));
  });
});
